// ================= PLY ASCII FALLBACK LOADER (DTM meshes) =====================
// Supports PLY files produced by dtm_to_ply_converter.cpp:
//  format ascii 1.0
//  element vertex N
//    properties (at least x y z; may include nx ny nz latitude longitude elevation)
//  element face M
//    property list uchar int vertex_indices
//  faces: "3 v0 v1 v2"
static bool loadAsciiDTMPLY(
    const std::string& filename,
    std::shared_ptr<Mesh>& mesh_out)
{
    std::ifstream in(filename);
    if (!in.is_open()) {
        std::cerr << "[PLY-Fallback] Cannot open file: " << filename << "\n";
        return false;
    }

    auto trim = [](const std::string& s) -> std::string {
        size_t a = 0, b = s.size();
        while (a < b && std::isspace(static_cast<unsigned char>(s[a]))) ++a;
        while (b > a && std::isspace(static_cast<unsigned char>(s[b-1]))) --b;
        return s.substr(a, b - a);
    };

    std::string line;
    bool header_done = false;
    size_t num_vertices = 0;
    size_t num_faces = 0;
    std::vector<std::string> vprops;
    bool format_ascii = false;
    std::string current_element;

    while (!header_done && std::getline(in, line)) {
        line = trim(line);
        if (line.empty()) continue;

        std::istringstream ls(line);
        std::string tok;
        ls >> tok;

        if (tok == "ply") continue;
        if (tok == "comment") continue;

        if (tok == "format") {
            std::string fmt; ls >> fmt;
            if (fmt.rfind("ascii", 0) == 0) format_ascii = true;
            else {
                std::cerr << "[PLY-Fallback] Non-ASCII format (" << fmt << ") unsupported by fallback\n";
                return false;
            }
        } else if (tok == "element") {
            std::string name; size_t count = 0;
            ls >> name >> count;
            current_element = name;
            if (name == "vertex") num_vertices = count;
            else if (name == "face") num_faces = count;
        } else if (tok == "property") {
            if (current_element == "vertex") {
                std::string type, name;
                ls >> type >> name;
                if (!name.empty()) vprops.push_back(name);
            } else if (current_element == "face") {
                // property list uchar int vertex_indices (ignore extras)
            }
        } else if (tok == "end_header") {
            header_done = true;
            break;
        }
    }

    if (!format_ascii || num_vertices == 0 || num_faces == 0) {
        std::cerr << "[PLY-Fallback] Invalid header (format_ascii=" << format_ascii
                  << ", vertices=" << num_vertices << ", faces=" << num_faces << ")\n";
        return false;
    }

    auto findProp = [&](const std::string& name)->int {
        for (size_t i=0;i<vprops.size();++i)
            if (vprops[i]==name) return static_cast<int>(i);
        return -1;
    };

    int ix = findProp("x"), iy = findProp("y"), iz = findProp("z");
    if (ix < 0 || iy < 0 || iz < 0) {
        std::cerr << "[PLY-Fallback] Missing required x/y/z properties\n";
        return false;
    }

    // Read vertices
    std::vector<std::array<double,3>> vertices;
    vertices.reserve(num_vertices);

    size_t v_read = 0;
    while (v_read < num_vertices && std::getline(in, line)) {
        line = trim(line);
        if (line.empty()) continue;

        std::istringstream ls(line);
        std::vector<double> vals(vprops.size());
        for (size_t k=0;k<vprops.size();++k) {
            if (!(ls >> vals[k])) {
                std::cerr << "[PLY-Fallback] Malformed vertex line " << v_read << "\n";
                return false;
            }
        }
        vertices.push_back({ vals[ix], vals[iy], vals[iz] });
        ++v_read;
    }

    if (v_read != num_vertices) {
        std::cerr << "[PLY-Fallback] Vertex count mismatch read=" << v_read
                  << " expected=" << num_vertices << "\n";
        return false;
    }

    // Read faces
    std::vector<std::array<int,3>> faces;
    faces.reserve(num_faces);
    size_t f_read = 0;
    while (f_read < num_faces && std::getline(in, line)) {
        line = trim(line);
        if (line.empty()) continue;

        std::istringstream ls(line);
        int n;
        if (!(ls >> n)) {
            std::cerr << "[PLY-Fallback] Malformed face line " << f_read << "\n";
            return false;
        }
        if (n != 3) {
            for (int k = 0; k < n; ++k) { int dummy; ls >> dummy; }
            continue;
        }
        int a,b,c;
        if (!(ls >> a >> b >> c)) {
            std::cerr << "[PLY-Fallback] Face indices parse error at face " << f_read << "\n";
            return false;
        }
        if (a<0||b<0||c<0||a>=static_cast<int>(num_vertices)||b>=static_cast<int>(num_vertices)||c>=static_cast<int>(num_vertices)) {
            std::cerr << "[PLY-Fallback] Face index out of range at face " << f_read << "\n";
            return false;
        }
        faces.push_back({a,b,c});
        ++f_read;
    }

    if (faces.size() < num_faces * 0.9) {
        std::cerr << "[PLY-Fallback] Parsed only " << faces.size() << "/" << num_faces
                  << " faces (<90%) aborting\n";
        return false;
    }

    // Build mesh
    mesh_out = std::make_shared<Mesh>();
    mesh_out->vertices = std::move(vertices);
    mesh_out->faces    = std::move(faces);

    // Compute face centers & normals and lat/lon
    const size_t F = mesh_out->faces.size();
    mesh_out->face_centers.resize(F);
    mesh_out->face_normals.resize(F);
    mesh_out->latitudes.resize(F);
    mesh_out->longitudes.resize(F);

    #pragma omp parallel for schedule(static)
    for (size_t i=0; i<F; ++i) {
        const auto& tri = mesh_out->faces[i];
        const auto& v1 = mesh_out->vertices[tri[0]];
        const auto& v2 = mesh_out->vertices[tri[1]];
        const auto& v3 = mesh_out->vertices[tri[2]];

        std::array<double,3> c = {
            (v1[0]+v2[0]+v3[0])/3.0,
            (v1[1]+v2[1]+v3[1])/3.0,
            (v1[2]+v2[2]+v3[2])/3.0
        };
        mesh_out->face_centers[i] = c;

        std::array<double,3> e1 = { v2[0]-v1[0], v2[1]-v1[1], v2[2]-v1[2] };
        std::array<double,3> e2 = { v3[0]-v1[0], v3[1]-v1[1], v3[2]-v1[2] };
        std::array<double,3> n = {
            e1[1]*e2[2]-e1[2]*e2[1],
            e1[2]*e2[0]-e1[0]*e2[2],
            e1[0]*e2[1]-e1[1]*e2[0]
        };
        double L = std::sqrt(n[0]*n[0]+n[1]*n[1]+n[2]*n[2]);
        if (L>0) { n[0]/=L; n[1]/=L; n[2]/=L; }
        // outward
        double dot = c[0]*n[0]+c[1]*n[1]+c[2]*n[2];
        if (dot < 0) { n[0] = -n[0]; n[1] = -n[1]; n[2] = -n[2]; }
        mesh_out->face_normals[i] = n;

        double r = std::sqrt(c[0]*c[0]+c[1]*c[1]+c[2]*c[2]);
        double lat = (r > 0) ? std::asin(c[2]/r) * RAD_TO_DEG : 0.0;
        double lon = std::atan2(c[1], c[0]) * RAD_TO_DEG;
        mesh_out->latitudes[i]  = lat;
        mesh_out->longitudes[i] = lon;
    }

    mesh_out->setProperty("is_custom_mesh", "true");
    mesh_out->setProperty("source_file", filename);
    std::cout << "[PLY-Fallback] Loaded ASCII PLY: vertices=" << mesh_out->vertices.size()
              << " faces=" << mesh_out->faces.size() << "\n";
    return true;
}

// Wrapper: try standard MeshUtils import; if it fails and file is .ply ASCII DTM, use fallback
static bool importMeshWithFallback(const std::string& filename,
                                   std::shared_ptr<Mesh>& mesh_out,
                                   double scale_factor = 1.0)
{
    MeshUtils mu;
    if (mu.importTriangulatedMesh(filename, scale_factor)) {
        mesh_out = mu.getMesh();
        return true;
    }

    // fallback only for .ply
    std::string ext;
    auto p = filename.find_last_of('.');
    if (p != std::string::npos) {
        ext = filename.substr(p + 1);
        std::transform(ext.begin(), ext.end(), ext.begin(), ::tolower);
    }
    if (ext == "ply") {
        std::cerr << "[Mesh Import] Standard loader failed; attempting ASCII fallback...\n";
        if (loadAsciiDTMPLY(filename, mesh_out)) {
            if (scale_factor != 1.0 && mesh_out) {
                #pragma omp parallel for schedule(static)
                for (size_t i = 0; i < mesh_out->vertices.size(); ++i) {
                    mesh_out->vertices[i][0] *= scale_factor;
                    mesh_out->vertices[i][1] *= scale_factor;
                    mesh_out->vertices[i][2] *= scale_factor;
                }
                // recompute centers only (normals unchanged length-1)
                #pragma omp parallel for schedule(static)
                for (size_t i = 0; i < mesh_out->faces.size(); ++i) {
                    const auto& f = mesh_out->faces[i];
                    const auto& a = mesh_out->vertices[f[0]];
                    const auto& b = mesh_out->vertices[f[1]];
                    const auto& c = mesh_out->vertices[f[2]];
                    mesh_out->face_centers[i] = {
                        (a[0]+b[0]+c[0])/3.0,
                        (a[1]+b[1]+c[1])/3.0,
                        (a[2]+b[2]+c[2])/3.0
                    };
                }
            }
            return true;
        }
        std::cerr << "[Mesh Import] Fallback also failed.\n";
    }
    return false;
}
// ================= END PLY ASCII FALLBACK LOADER =====================

// Constants for albedo processing
namespace {
    // Minimum physically plausible albedo for icy surfaces
    // Ice has albedo typically 0.5+, but allowing down to 0.05 for "dirty" ice
    constexpr double MIN_VALID_ALBEDO = 0.01;
    
    // Maximum physically plausible albedo (pure white ice/snow)
    constexpr double MAX_VALID_ALBEDO = 0.99;
    
    // Default visible albedo if no valid value is found
    constexpr double DEFAULT_ICE_ALBEDO = 0.55;
}

// ---------------------------------------------------------------------------
// PTM-09 class: format a small dimensionless number (an albedo, a Hayne
// coefficient) through a LOCAL stream.
//
// std::cout arrives at the albedo banners already carrying
// `std::fixed << std::setprecision(1)` left set by an earlier progress line
// (the chunked-illumination "Extracting data: X.X%" report, and friends). Under
// that state the Moon's A0 = 0.12 prints as "0.1", the Hayne et al. (2017)
// coefficients a = 0.06 and b = 0.25 print as "0.1" and "0.2" -- three distinct
// numbers rendered as two, and a run reporting values it did not use. That cost
// a runner a bug chase on 2026-08-17 (it reads exactly like a hard-coded 0.1
// albedo). Same archetype as PTM-05/PTM-55 and the conductivity-model banner at
// the `std::ostringstream cmb` site further down: a local stream starts in the
// default format and cannot inherit std::cout's state.
static inline std::string fmtSig(double v, int sig = 6) {
    std::ostringstream os;
    os << std::defaultfloat << std::setprecision(sig) << v;
    return os.str();
}

// ---------------------------------------------------------------------------
// Infrared absorptivity -- THE single definition, by Kirchhoff's law.
//
// A surface absorbs thermal infrared with exactly the efficiency it emits it,
// so the infrared absorptivity is not a free constant: it IS the emissivity,
// and the "IR albedo" is only ever 1 - emissivity. The same number therefore
// has to appear in all three places:
//   * here, absorbing the primary body's infrared (Earth-shine, Jupiter-shine);
//   * in the surface boundary condition, emitting eps*sigma*T^4
//     (thermal_model.cpp: `this->emissivity = planet.emissivity`);
//   * in the radiosity solver, scattering rho = 1 - eps
//     (radiation_exchange.cpp: `reflectivity_[i] = 1.0 - emissivity_[i]`).
//
// It used to be none of those. `DEFAULT_IR_ALBEDO = 0.1` was a bare constant
// from which an "IR emissivity" of 1 - 0.1 = 0.90 was DERIVED -- the dependency
// inverted -- while the callers that bypassed that override implied
// 1 - 0.02 = 0.98, and the GPU path had used planet.emissivity all along. On
// the Moon (emissivity 0.95, Hayne et al. 2017) the engine absorbed infrared as
// though eps were 0.90 or 0.98 while emitting with 0.95 and scattering with
// 0.95. Absorption and emission disagreed, and nothing said so.
//
// To move it, override the BODY's emissivity (thermophysical.emissivity_override,
// which is echoed at startup) so all three move together. There is deliberately
// no way to move this one alone, and recordIrAbsorptivity() below cross-checks
// at runtime that nothing managed it anyway.
static inline double thermalIrEmissivity(const thermal::Planet& planet) {
    return planet.emissivity;
}

// Kirchhoff cross-check (gate G1). Every site that absorbs primary infrared
// records the emissivity it actually used; reportKirchhoffConsistency() compares
// the set against the emissivity the radiosity solver was given and the one the
// surface BC emits with. Arranging the three to agree is not the same as knowing
// they agree -- the CPU SIMD-batch path rebuilds its own Planet, and
// PTM_RAD_EMISSIVITY can move the radiosity's copy on its own.
static std::mutex               g_ir_eps_mutex;
static std::map<std::string, double> g_ir_eps_used;   // site tag -> emissivity

static void recordIrAbsorptivity(const char* site, double eps) {
    std::lock_guard<std::mutex> lk(g_ir_eps_mutex);
    g_ir_eps_used[site] = eps;
}

// The emissivity the radiosity solver operatively held, snapshotted while the
// manager was alive so the end-of-run check can still see it. Empty when
// radiation is off or the solver never initialized.
static std::vector<double> g_radiosity_eps_snapshot;

// Gate G1. Compare, for this run:
//   * every emissivity an infrared-ABSORPTION site actually used;
//   * the emissivity the surface BC EMITS with (planet.emissivity, which
//     thermal_model.cpp copies verbatim into Model::emissivity);
//   * the emissivity the radiosity solver operatively holds AFTER its own
//     PTM_RAD_EMISSIVITY override, which is the one way the three can still
//     come apart.
// `radiosity_eps` is empty when radiation is off; the absorption/emission
// identity is still checked. Returns false if the identity is broken.
static bool reportKirchhoffConsistency(double emit_eps,
                                       const std::vector<double>* radiosity_eps) {
    std::lock_guard<std::mutex> lk(g_ir_eps_mutex);
    if (g_ir_eps_used.empty()) {
        std::cerr << "[kirchhoff] WARNING: no infrared-absorption site reported an "
                     "emissivity this run, so the Kirchhoff identity could NOT be "
                     "checked. Do not quote this run as consistent." << std::endl;
        return true;   // nothing absorbed IR; not a failure, but say so
    }

    // Exact equality is the right test: every site reads the same double off the
    // same Planet field, so any difference at all means a second source crept in.
    bool ok = true;
    std::ostringstream sites;
    for (const auto& kv : g_ir_eps_used) {
        sites << " " << kv.first << "=" << std::setprecision(17) << kv.second;
        if (kv.second != emit_eps) ok = false;
    }

    double rad_min = 0.0, rad_max = 0.0;
    bool have_rad = (radiosity_eps && !radiosity_eps->empty());
    if (have_rad) {
        rad_min = *std::min_element(radiosity_eps->begin(), radiosity_eps->end());
        rad_max = *std::max_element(radiosity_eps->begin(), radiosity_eps->end());
        if (rad_min != emit_eps || rad_max != emit_eps) ok = false;
    }

    std::ios_base::fmtflags fl(std::cout.flags());
    std::streamsize pr = std::cout.precision();
    if (ok) {
        std::cout << "[kirchhoff] absorb == emit == scatter: eps = "
                  << std::defaultfloat << std::setprecision(6) << emit_eps
                  << " (IR albedo " << (1.0 - emit_eps) << ") at"
                  << sites.str() << ", emit=" << emit_eps;
        if (have_rad) std::cout << ", radiosity=[" << rad_min << ", " << rad_max << "]";
        else          std::cout << ", radiosity=n/a (radiation off)";
        std::cout << std::endl;
    } else {
        std::cerr << "\nFATAL [kirchhoff]: a surface must absorb thermal infrared with the "
                     "same efficiency it emits it, and this run does not.\n"
                  << "  absorption sites:" << sites.str() << "\n"
                  << "  surface BC emits with: " << std::setprecision(17) << emit_eps << "\n";
        if (have_rad) {
            std::cerr << "  radiosity scatters 1-eps with eps in [" << rad_min << ", "
                      << rad_max << "]"
                      << (std::getenv("PTM_RAD_EMISSIVITY")
                            ? "  <-- PTM_RAD_EMISSIVITY is set; it moves ONLY the radiosity"
                            : "")
                      << "\n";
        }
        std::cerr << "  Energy is not conserved between absorption and emission.\n";
        // Enforcement fails by DEFAULT, with an informed override -- a deliberate
        // consistency study (that is what PTM_RAD_EMISSIVITY exists for) must
        // still be possible, but only by saying so, and it stays in the log.
        if (std::getenv("PTM_ALLOW_KIRCHHOFF_VIOLATION")) {
            std::cerr << "  PTM_ALLOW_KIRCHHOFF_VIOLATION is set: CONTINUING ANYWAY. This run "
                         "is a deliberate inconsistency study, NOT a physical result -- do not "
                         "publish it or compare it against a run without the override."
                      << std::endl;
            ok = true;
        } else {
            std::cerr << "  Refusing to present this run as physical. Set "
                         "PTM_ALLOW_KIRCHHOFF_VIOLATION=1 to run it anyway as an explicit "
                         "inconsistency study." << std::endl;
        }
    }
    std::cout.flags(fl);
    std::cout.precision(pr);
    return ok;
}

// Thread-safe output suppressor class
class OutputSuppressor {
private:
    std::streambuf* original_buffer;
    bool active;
    static std::ofstream null_stream;
    static int ref_count;
    static std::mutex mtx;

public:
    OutputSuppressor() : active(false), original_buffer(nullptr) {
        suppress();
    }
    
    void suppress() {
        std::lock_guard<std::mutex> lock(mtx);
        if (!active) {
            if (ref_count == 0) {
                // Only open the null stream once
                null_stream.open("/dev/null");
            }
            ref_count++;
            original_buffer = std::cout.rdbuf();
            std::cout.rdbuf(null_stream.rdbuf());
            active = true;
        }
    }
    
    void resume() {
        std::lock_guard<std::mutex> lock(mtx);
        if (active) {
            std::cout.rdbuf(original_buffer);
            ref_count--;
            if (ref_count == 0) {
                null_stream.close();
            }
            active = false;
        }
    }
    
    ~OutputSuppressor() {
        resume();
    }
};

// Initialize static members
std::ofstream OutputSuppressor::null_stream;
int OutputSuppressor::ref_count = 0;
std::mutex OutputSuppressor::mtx;

// Thread-safe stderr progress bar class
class StderrProgressBar {
private:
    int total;
    int barWidth;
    std::string prefix;
    bool showProgress;
    std::mutex mtx; // Add mutex for thread safety
    int last_percentage; // Track last percentage to reduce updates

public:
    StderrProgressBar(int total, const std::string& prefix, int barWidth, bool showProgress)
        : total(total), barWidth(barWidth), prefix(prefix), showProgress(showProgress), last_percentage(-1) {}
    
    void update(int current) {
        if (!showProgress) return;
        
        // Calculate current percentage
        int percentage = static_cast<int>((static_cast<float>(current) / total) * 100.0);
        
        // Only update if percentage has changed to reduce mutex contention
        if (percentage == last_percentage && percentage != 100)
            return;
        
        // Lock mutex for thread-safe stderr access
        std::lock_guard<std::mutex> lock(mtx);
        
        // Only update if percentage has changed (double-check after lock)
        if (percentage != last_percentage || percentage == 100) {
            last_percentage = percentage;
            
            float progress = static_cast<float>(current) / total;
            int pos = static_cast<int>(barWidth * progress);
            
            std::cerr << "\r" << prefix << " [";
            for (int i = 0; i < barWidth; ++i) {
                if (i < pos) std::cerr << "=";
                else if (i == pos) std::cerr << ">";
                else std::cerr << " ";
            }
            std::cerr << "] " << percentage << "%";
            std::cerr.flush();
        }
    }
    
    void finish() {
        if (!showProgress) return;
        
        // Lock mutex for thread-safe stderr access
        std::lock_guard<std::mutex> lock(mtx);
        
        std::cerr << "\r" << prefix << " [";
        for (int i = 0; i < barWidth; ++i) {
            std::cerr << "=";
        }
        std::cerr << "] 100%" << std::endl;
    }
};

